-- Guarded cleanup of inert legacy resource child pools, batch 03.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (1617,1622,1624,1632,1643,1646,1648,1650,1652,1653,1658,1660,1665,1667,1668,1670,1673,1675,1679,1680,1681,1694,1696,1698,1701,1707,1718,1719,1720,1722,1723,1724,1725,1729,1733,1734,1737,1739,1740,1750,1753,1756,1760,1763,1766,1767,1782,1784,1788,1789) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (1617,1622,1624,1632,1643,1646,1648,1650,1652,1653,1658,1660,1665,1667,1668,1670,1673,1675,1679,1680,1681,1694,1696,1698,1701,1707,1718,1719,1720,1722,1723,1724,1725,1729,1733,1734,1737,1739,1740,1750,1753,1756,1760,1763,1766,1767,1782,1784,1788,1789) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

